const items = $input.all();

if (items.length === 0) {
  return [{ 
    json: { 
      mensaje_telegram: "Actualmente no tienes tutorías registradas para este ID." 
    } 
  }];
}

const listaTutorias = items.map(item => {
  const tutoria = item.json;

  return `- ID: ${tutoria.id_tutoria} - ${tutoria.materia} (Estado: ${tutoria.estado})`;
}).join("\n");

const mensajeFinal = `Este es el detalle de las tutorías solicitadas:\n\n${listaTutorias}\n\nIngresa el ID de la tutoria a Cancelar`;

return [{ 
  json: { 
    mensaje_telegram: mensajeFinal 
  } 
}];

// 1. Obtener los datos del trigger y del estado anterior
const mensajeTelegram = $('Telegram Trigger').first().json.message.text;
const datosSesion = $('Get row(s) in sheet').first().json;

// 2. Extraer la materia guardada por tu compañero en el paso anterior
// Nota: Tu compañero guarda la materia en "datos_parciales" (ej: "Matemática")
const materia = datosSesion.datos_parciales;

// 3. Convertir fecha de DD-MM-YYYY a YYYY-MM-DD
// El mensaje actual de Telegram contiene la fecha validada por el Regex de tu compañero
const partesFecha = mensajeTelegram.split('-'); // [DD, MM, YYYY]
const fechaISO = `${partesFecha[2]}-${partesFecha[1]}-${partesFecha[0]}`; // YYYY-MM-DD

return [{
  json: {
    telegram_user: datosSesion.telegram_user,
    materia_buscar: materia,
    fecha_buscar: fechaISO
  }
}];

// 1. Obtenemos los datos del tutor que entran directo a este nodo
const tutorData = $input.item.json;

// 2. Buscamos la fecha directamente usando la propiedad nativa de n8n context
const fechaTexto = $('Formatear Datos de Entrada').first().json.fecha_buscar;

// 3. Arreglo de días en español
const diasSemana = ["Domingo", "Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado"];

// 4. Calculamos el día de la semana de manera segura
const fechaObjeto = new Date(fechaTexto + 'T00:00:00');
const diaCalculado = diasSemana[fechaObjeto.getDay()];

// 5. Retornamos la unión limpia de los datos
return [{
  json: {
    ...tutorData, // id_tutor, nombre, especialidad_materias, estado
    dia_semana_buscar: diaCalculado,
    fecha_buscar: fechaTexto
  }
}];

