// Captura todas las filas que vienen de Google Sheets
const filas = typeof $input.all === 'function' ? $input.all() : [];

let agendadas = 0;
let canceladas = 0;
let realizadas = 0;

// Recorre cada fila y cuenta según el estado
for (const fila of filas) {
  const estado = fila.json.estado ? fila.json.estado.toLowerCase().trim() : '';

  if (estado === 'agendada') {
    agendadas++;
  } else if (estado === 'cancelada') {
    canceladas++;
  } else if (estado === 'completada' || estado === 'realizada') {
    realizadas++;
  }
}

const totalTutorias = agendadas + canceladas + realizadas;

// Devuelve los totales listos para el correo electrónico
return [
  {
    json: {
      total: totalTutorias,
      agendadas: agendadas,
      canceladas: canceladas,
      realizadas: realizadas,
      fecha_reporte: new Date().toLocaleDateString('es-ES')
    }
  }
];

