manana.setDate(hoy.getDate() + 1);

// Extrae el día, mes y año de forma individual
const dia = String(manana.getDate()).padStart(2, '0');
const mes = String(manana.getMonth() + 1).padStart(2, '0'); // Los meses van de 0 a 11
const ano = manana.getFullYear();

// Une los datos con guiones (Ejemplo: 11-07-2026)
const fechaFormateadaLatina = `${dia}-${mes}-${ano}`;

